00049 // Generate cost for each block
00050 //
00051 Surface TemporalCost_2x2::process(const Surface &sour_plane, const Surface &reco_plane, const Surface *symb_plane,
00052                                   unsigned transform_block_size, unsigned scale, bool intra) {
00053 
00054     CHECK(sour_plane.width() == reco_plane.width() && sour_plane.height() == reco_plane.height());
00055     CHECK(sour_plane.width() == symb_plane[0].width() * transform_block_size &&
00056           sour_plane.height() == symb_plane[0].height() * transform_block_size);
00057 
00058     const auto src = sour_plane.view_as<int16_t>();
00059     const auto recon = reco_plane.view_as<int16_t>();
00060     const auto symb00 = symb_plane[0].view_as<int16_t>();
00061     const auto symb01 = symb_plane[1].view_as<int16_t>();
00062     const auto symb02 = symb_plane[2].view_as<int16_t>();
00063     const auto symb03 = symb_plane[3].view_as<int16_t>();
00064 
00065     const unsigned dst_width = src.width() / transform_block_size;
00066     const unsigned dst_height = src.height() / transform_block_size;
00067     const float    lambda     = ((float)(scale) *0.6f);
00068 
00069     return Surface::build_from<int16_t>()
00070         .generate(dst_width, dst_height,
00071                   [&](unsigned block_x, unsigned block_y) -> int16_t {
00072                       // SAD term
00073                       int32_t t0 = 0;
00074                       for (unsigned int x = (block_x)*transform_block_size; x < (block_x + 1) * transform_block_size; ++x) {
00075                           for (unsigned int y = (block_y)*transform_block_size; y < (block_y + 1) * transform_block_size; ++y) {
00076                               t0 += abs(src.read(x, y) - recon.read(x, y));
00077                           }
00078                       }
00079 
00080                       // non zero coefficients term
00081                       int32_t t1 = 0;
00082                       t1 = (symb00.read(block_x, block_y) ? 1 : 0) + (intra ? 1 : (symb01.read(block_x, block_y) ? 1 : 0)) +
00083                            (symb02.read(block_x, block_y) ? 1 : 0) + (symb03.read(block_x, block_y) ? 1 : 0);
00084 
00085                       // Intra signalling term
00086                       int32_t t2 = 0;
00087 
00088                       float fCost = (float)(t0 + (lambda  * (t1 + t2)));
00089                       int32_t iCost = (fCost < ((1 << 15) - 1) ? (int)fCost : ((1 << 15) - 1));
00090                       return (int16_t)(iCost);
00091                   })
00092         .finish();
00093 }
00094 
00095 Surface TemporalCost_4x4::process(const Surface &sour_plane, const Surface &reco_plane, const Surface *symb_plane,
00096                                   unsigned transform_block_size, unsigned scale, bool intra) {
00097 
00098     CHECK(sour_plane.width() == reco_plane.width() && sour_plane.height() == reco_plane.height());
00099     CHECK(sour_plane.width() == symb_plane[0].width() * transform_block_size &&
00100           sour_plane.height() == symb_plane[0].height() * transform_block_size);
00101 
00102     const auto src = sour_plane.view_as<int16_t>();
00103     const auto recon = reco_plane.view_as<int16_t>();
00104     const auto symb00 = symb_plane[0].view_as<int16_t>();
00105     const auto symb01 = symb_plane[1].view_as<int16_t>();
00106     const auto symb02 = symb_plane[2].view_as<int16_t>();
00107     const auto symb03 = symb_plane[3].view_as<int16_t>();
00108     const auto symb04 = symb_plane[4].view_as<int16_t>();
00109     const auto symb05 = symb_plane[5].view_as<int16_t>();
00110     const auto symb06 = symb_plane[6].view_as<int16_t>();
00111     const auto symb07 = symb_plane[7].view_as<int16_t>();
00112     const auto symb08 = symb_plane[8].view_as<int16_t>();
00113     const auto symb09 = symb_plane[9].view_as<int16_t>();
00114     const auto symb10 = symb_plane[10].view_as<int16_t>();
00115     const auto symb11 = symb_plane[11].view_as<int16_t>();
00116     const auto symb12 = symb_plane[12].view_as<int16_t>();
00117     const auto symb13 = symb_plane[13].view_as<int16_t>();
00118     const auto symb14 = symb_plane[14].view_as<int16_t>();
00119     const auto symb15 = symb_plane[15].view_as<int16_t>();
00120 
00121     const unsigned dst_width = src.width() / transform_block_size;
00122     const unsigned dst_height = src.height() / transform_block_size;
00123 
00124     return Surface::build_from<int16_t>()
00125         .generate(dst_width, dst_height,
00126                   [&](unsigned block_x, unsigned block_y) -> int16_t {
00127                       // SAD term
00128                       int32_t t0 = 0;
00129                       for (unsigned int x = (block_x)*transform_block_size; x < (block_x + 1) * transform_block_size; ++x) {
00130                           for (unsigned int y = (block_y)*transform_block_size; y < (block_y + 1) * transform_block_size; ++y) {
00131                               t0 += abs(src.read(x, y) - recon.read(x, y));
00132                           }
00133                       }
00134 
00135                       // non zero residuals term
00136                       int32_t t1 = 0;
00137                       t1 = (symb00.read(block_x, block_y) ? 1 : 0) + (symb01.read(block_x, block_y) ? 1 : 0) +
00138                            (symb02.read(block_x, block_y) ? 1 : 0) + (symb03.read(block_x, block_y) ? 1 : 0) +
00139                            (symb04.read(block_x, block_y) ? 1 : 0) + (intra ? 1 : (symb05.read(block_x, block_y) ? 1 : 0)) +
00140                            (symb06.read(block_x, block_y) ? 1 : 0) + (symb07.read(block_x, block_y) ? 1 : 0) +
00141                            (symb08.read(block_x, block_y) ? 1 : 0) + (symb09.read(block_x, block_y) ? 1 : 0) +
00142                            (symb10.read(block_x, block_y) ? 1 : 0) + (symb11.read(block_x, block_y) ? 1 : 0) +
00143                            (symb12.read(block_x, block_y) ? 1 : 0) + (symb13.read(block_x, block_y) ? 1 : 0) +
00144                            (symb14.read(block_x, block_y) ? 1 : 0) + (symb15.read(block_x, block_y) ? 1 : 0);
00145 
00146                       // Intra signalling term
00147                       int32_t t2 = 0;
00148 
00149                       float fCost = (float)(t0 + scale * (t1 + t2));
00150                       int32_t iCost = (fCost < ((1 << 15) - 1) ? (int)fCost : ((1 << 15) - 1));
00151                       return (int16_t)(iCost);
00152                   })
00153         .finish();
00154 }
