00156 // Calculate temporal cost solely based on SAD, used for no_enhancement part
00157 Surface TemporalCost_SAD::process(const Surface &sour_plane, const Surface &reco_plane, unsigned transform_block_size) {
00158     const unsigned dst_width = sour_plane.width() / transform_block_size;
00159     const unsigned dst_height = sour_plane.height() / transform_block_size;
00160 
00161     if (!reco_plane.empty()) {
00162         // SAD
00163         CHECK(sour_plane.width() == reco_plane.width() && sour_plane.height() == reco_plane.height());
00164         const auto src = sour_plane.view_as<int16_t>();
00165         const auto recon = reco_plane.view_as<int16_t>();
00166         return Surface::build_from<int16_t>()
00167             .generate(dst_width, dst_height,
00168                       [&](unsigned block_x, unsigned block_y) -> int16_t {
00169                           // SAD term
00170                           int32_t t0 = 0;
00171                           for (unsigned int x = (block_x)*transform_block_size; x < (block_x + 1) * transform_block_size; ++x) {
00172                               for (unsigned int y = (block_y)*transform_block_size; y < (block_y + 1) * transform_block_size; ++y) {
00173                                   t0 += abs(src.read(x, y) - recon.read(x, y));
00174                               }
00175                           }
00176                           int32_t iCost = (t0 < ((1 << 15) - 1) ? (int)t0 : ((1 << 15) - 1));
00177                           return (int16_t)(iCost);
00178                       })
00179             .finish();
00180     } else if (sour_plane.bpp() == 1) {
00181         // Sum of absolute values (uint8_t)
00182         const auto src = sour_plane.view_as<uint8_t>();
00183         return Surface::build_from<int16_t>()
00184             .generate(dst_width, dst_height,
00185                       [&](unsigned block_x, unsigned block_y) -> int16_t {
00186                           // SAD term
00187                           int32_t t0 = 0;
00188                           for (unsigned int x = (block_x)*transform_block_size; x < (block_x + 1) * transform_block_size; ++x) {
00189                               for (unsigned int y = (block_y)*transform_block_size; y < (block_y + 1) * transform_block_size; ++y) {
00190                                   t0 += abs(src.read(x, y));
00191                               }
00192                           }
00193                           int32_t iCost = (t0 < ((1 << 15) - 1) ? (int)t0 : ((1 << 15) - 1));
00194                           return (int16_t)(iCost);
00195                       })
00196             .finish();
00197     } else {
00198         // Sum of absolute values (uint16_t)
00199         const auto src = sour_plane.view_as<uint16_t>();
00200         return Surface::build_from<int16_t>()
00201             .generate(dst_width, dst_height,
00202                       [&](unsigned block_x, unsigned block_y) -> int16_t {
00203                           // SAD term
00204                           int32_t t0 = 0;
00205                           for (unsigned int x = (block_x)*transform_block_size; x < (block_x + 1) * transform_block_size; ++x) {
00206                               for (unsigned int y = (block_y)*transform_block_size; y < (block_y + 1) * transform_block_size; ++y) {
00207                                   t0 += abs(src.read(x, y));
00208                               }
00209                           }
00210                           int32_t iCost = (t0 < ((1 << 15) - 1) ? (int)t0 : ((1 << 15) - 1));
00211                           return (int16_t)(iCost);
00212                       })
00213             .finish();
00214     }
00215 }
