00217 // Given the new temporal buffer, the previous temporal buffer and the signalling mask - generate the transmitted residuals
00218 //
00219 Surface TemporalSelect::process(const Surface &inter_plane, const Surface &intra_plane, const Surface &mask_plane) {
00220 
00221     CHECK(inter_plane.width() == intra_plane.width() && inter_plane.height() == intra_plane.height());
00222 
00223     // Scale the mask to cover source images
00224     const unsigned block_w = tile_size(mask_plane.width(), inter_plane.width());
00225     const unsigned block_h = tile_size(mask_plane.height(), inter_plane.height());
00226     const unsigned shift_w = log2(block_w);
00227     const unsigned shift_h = log2(block_h);
00228 
00229     const auto src_inter = inter_plane.view_as<int16_t>();
00230     const auto src_intra = intra_plane.view_as<int16_t>();
00231     const auto src_mask = mask_plane.view_as<uint8_t>();
00232 
00233     return Surface::build_from<int16_t>()
00234         .generate(src_inter.width(), src_inter.height(),
00235                   [&](unsigned x, unsigned y) -> int16_t {
00236                       if (src_mask.read(x >> shift_w, y >> shift_h) == TemporalType::TEMPORAL_PRED) {
00237                           return src_inter.read(x, y);
00238                       } else {
00239                           return src_intra.read(x, y);
00240                       }
00241                   })
00242         .finish();
00243 }
00244 
00245 // Insert the single-bit-per-transform signalling as a mask
00246 //
00247 Surface TemporalInsertMask::process(const Surface &symbols, const Surface &mask, const bool refresh) {
00248     const auto src_symbols = symbols.view_as<int16_t>();
00249 
00250     if (!mask.empty() && !refresh) {
00251         CHECK(symbols.width() == mask.width() && symbols.height() == mask.height());
00252         const auto src_mask = mask.view_as<uint8_t>();
00253 
00254         return Surface::build_from<int16_t>()
00255             .generate(src_symbols.width(), src_symbols.height(),
00256                       [&](unsigned x, unsigned y) -> int16_t {
00257                           return (src_symbols.read(x, y) * 2) | (src_mask.read(x, y) == TemporalType::TEMPORAL_INTR ? 1 : 0);
00258                       })
00259             .finish();
00260     } else {
00261         return Surface::build_from<int16_t>()
00262             .generate(src_symbols.width(), src_symbols.height(),
00263                       [&](unsigned x, unsigned y) -> int16_t { return (src_symbols.read(x, y) * 2); })
00264             .finish();
00265     }
00266 }
00267 
00268 // Insert the user_data
00269 //
00270 Surface UserDataInsert::process(const Surface &symbols, UserDataMethod method, UserDataMode user_data, FILE* file) {
00271     unsigned size;
00272     switch (user_data) {
00273     case UserData_2bits:
00274         size = 2;
00275         break;
00276     case UserData_6bits:
00277         size = 6;
00278         break;
00279     default:
00280         CHECK(0);
00281     }
00282 
00283     const auto src_symbols = symbols.view_as<int16_t>();
00284     return Surface::build_from<int16_t>()
00285         .generate(src_symbols.width(), src_symbols.height(),
00286                   [&](unsigned x, unsigned y) -> int16_t {
00287                       int16_t value = src_symbols.read(x, y);
00288                       const bool sign = value < 0;
00289                       uint16_t value_abs = std::min((uint16_t)abs(value), (uint16_t)(((uint16_t)0x1fff) >> (size + 1)));
00290                       unsigned char data;
00291                       switch (method) {
00292                       case UserDataMethod_Zeros:
00293                           data = 0x00;
00294                           break;
00295                       case UserDataMethod_Ones:
00296                           data = 0xff;
00297                           break;
00298                       case UserDataMethod_FixedRandom:
00299                       case UserDataMethod_Random:
00300                           data = Random().rand();
00301                           break;
00302                       default:
00303                           CHECK(0);
00304                       }
00305                       data &= (size == 6 ? 0x3f : 0x03);
00306 #if USER_DATA_EXTRACTION
00307                       fwrite(&data, 1, 1, file);
00308 #endif
00309                       return (int16_t)(((value_abs << (size + 1)) | data) | (sign << size));
00310                   })
00311         .finish();
00312 }
